INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch12$PT139-S4-Q10$batch12$, 139, 4, 10, $batch12$Parallel$batch12$, $batch12$In a test of fuel efficiency, car X and car Y yielded the same average fuel mileage, even though car X was driven in a less fuel-efficient manner than car Y was. Thus, car X is more fuel efficient than car Y.$batch12$, $batch12$Which one of the following arguments is most similar in its reasoning to the argument above?$batch12$, $batch12$B$batch12$, true, $batch12$Batch 12; question text from local bank.$batch12$ FROM lr_sections s WHERE s.preptest=139 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT139-S4-Q10$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$A$batch12$, $batch12$In an experiment, subject X consistently gave lower pain ratings in response to pinpricks than subject Y did. Therefore, it is reasonable to conclude that subjects X and Y experience pain differently.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT139-S4-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$A$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$B$batch12$, $batch12$Our hamster gained the same amount of weight as our neighbors' hamster, even though our hamster ate more than theirs. So it must be that our hamster burned more calories than theirs did.$batch12$, $batch12$Correct$batch12$, true FROM lr_questions q WHERE q.qid=$batch12$PT139-S4-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$B$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$C$batch12$, $batch12$When on his bicycle, Roland makes better time coasting down a hill than pedaling on a horizontal path. So he would make even better time on the hills if he were to pedal rather than coast.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT139-S4-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$C$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$D$batch12$, $batch12$When asked to judge the value of various pieces of antique furniture, I gave lower estimates on average than you did. So in those cases where we both gave the same estimate, I must have overestimated the piece's value.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT139-S4-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$D$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$E$batch12$, $batch12$Jean demonstrates a high level of visual acuity when she wears prescription glasses. Thus, it must be that without those prescription glasses, she would demonstrate a lower level of visual acuity.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT139-S4-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$E$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT139-S4-Q10$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Car X is more fuel efficient than car Y.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Both got the same mileage, but X was driven less efficiently.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Same result despite a handicap, so the handicapped one must have an advantage in the underlying trait.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Same outcome, one faced a handicap, so that one is better at the underlying trait.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT139-S4-Q10$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Different ratings lead to a claim about different experience. No equal outcome despite a handicap.$batch12$), ($batch12$B$batch12$, $batch12$The hamsters gained the same weight even though ours ate more, so ours must burn more calories. Same move.$batch12$), ($batch12$C$batch12$, $batch12$This predicts that combining pedaling with hills would be even faster.$batch12$), ($batch12$D$batch12$, $batch12$This uses a general tendency to judge particular cases.$batch12$), ($batch12$E$batch12$, $batch12$This concludes what would happen without glasses. No equal outcome.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT139-S4-Q10$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
